int main(void){int sx,n;for(sx=276;sx<=304;sx+=2){BlCombat w;BlProgress p;bl_combat_reset(&w);bl_progress_reset(&p);bl_progress_inspect_room(&p,&w,1);w.enemy[1].respawn=0;w.enemy[0].active=1;w.enemy[0].health=20;w.enemy[0].stun=0;w.enemy[0].body.x=sx*16;w.enemy[0].body.y=146*16;w.enemy[0].body.previous_x=w.enemy[0].body.x;w.enemy[0].body.previous_y=w.enemy[0].body.y;w.player.body.x=(sx-14)*16;w.player.body.y=146*16;w.player.body.attack=BL_FLYING_KICK;w.player.body.attack_phase=3;w.player.body.facing=1;printf("START %d hit=%d\n",sx,bl_combat_contact(&w.player,&w.enemy[0],0));w.player.body.x=24*16;w.player.body.y=98*16;w.player.body.attack=BL_ATTACK_NONE;for(n=0;n<22;n++){bl_progress_step(&p,&w,0);printf("%d x=%d y=%d stun=%u wall=%u count=%u curR=%u oldR=%u transition=%u player=%d,%d active=%u\n",n,bl_x(&w.enemy[0].body),bl_y(&w.enemy[0].body),w.enemy[0].stun,w.enemy[0].body.wall.state,w.enemy[0].body.wall.counter,w.enemy[0].body.wall.moves[0][3],w.enemy[0].body.wall.moves[1][3],p.transitions,bl_x(&w.player.body),bl_y(&w.player.body),w.enemy[0].active);if(p.transitions)break;}}return 0;}
